import * as THREE from 'three/webgpu';
import { texture, uv, vec4, float, mix } from 'three/tsl';
import { createTextMesh } from '@/text';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-collection-title';

  const pos = config.scenePosition?.position ?? [0, 3, 0];
  const rot = config.scenePosition?.rotation ?? [0, 0, 0];
  const scl = config.scenePosition?.scale ?? [1, 1, 1];
  group.position.set(...pos);
  group.rotation.set(...rot);
  group.scale.set(...scl);

  const width = 2.6;
  const height = width * (320 / 512);

  const geometry = new THREE.PlaneGeometry(width, height);

  const imgTex = ctx.textureLoader('/prism-mock/home/nodes/feature-card.png');

  const ink = new THREE.Color('#16161d');
  const surface = new THREE.Color('#0b0b10');

  const material = new THREE.MeshBasicNodeMaterial();
  material.transparent = true;

  const baseTex = texture(imgTex, uv());
  const gradientMix = mix(
    vec4(surface.r, surface.g, surface.b, 1.0),
    vec4(ink.r, ink.g, ink.b, 1.0),
    uv().y
  );

  material.colorNode = mix(gradientMix, baseTex, float(0.55));

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'collection-title-plane';
  group.add(plane);

  let textMesh = null;
  try {
    textMesh = createTextMesh({
      text: 'Collection',
      font: 'Lora',
      weight: 400,
      sizeEm: 0.34,
      color: '#e8ecf2',
      fontAtlas: ctx.fontAtlas,
      align: 'center',
    });
    textMesh.position.set(0, 0, 0.01);
    group.add(textMesh);
  } catch (e) {
    // font atlas render failed silently; no fallback DOM text allowed
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (textMesh) {
      textMesh.geometry?.dispose?.();
      if (textMesh.material) {
        if (Array.isArray(textMesh.material)) {
          textMesh.material.forEach((m) => m.dispose());
        } else {
          textMesh.material.dispose();
        }
      }
    }
  };

  return group;
}
